def extract_raw(solution_str):
    if len(solution_str) > 300:
        solution_str = solution_str[-300:]
    answer = re.findall(r"(\-?[0-9\.\,]+)", solution_str)
    final=None
    for final in reversed(answer):
        if final not in ("", "."):
            break
    return final

def variants(a):
    if a is None: return []
    out=[a]
    b=a.replace(",","").replace("$","")
    out.append(b)
    b2=b.rstrip(".")
    out.append(b2)
    # strip trailing zeros after decimal
    if re.fullmatch(r"-?\d+\.\d+", b2):
        out.append(str(float(b2)))  # may be 132.0
        if float(b2)==int(float(b2)):
            out.append(str(int(float(b2))))
    return out

def norm_equal(raw, gt):
    if raw is None: return False
    gts={gt, gt.rstrip("."), str(gt)}
    try:
        if float(gt)==int(float(gt)):
            gts.add(str(int(float(gt))))
            gts.add(f"{int(float(gt))}.0")
            gts.add(f"{int(float(gt))}.00")
    except: pass
    for v in variants(raw):
        if v in gts: return True
        try:
            if abs(float(v.replace(",",""))-float(gt))<1e-4:
                return True
        except: pass
    return False

for label,path in [
    ("val0","results/grpo_gsm8k_seed42/val_generations/0.jsonl"),
