        raw=extract_raw(r["output"])
        logged=r["score"]==1
        exa = raw==r["gts"] if raw else False
        # reproduce library exactly
        if raw==r["gts"]:
            exact+=1
        soft_ok=norm_equal(raw, r["gts"])
        if soft_ok:
            soft+=1
        if soft_ok and not logged:
            soft_not_exact+=1
            if raw and "," in raw:
                reasons["comma"]+=1
            elif raw and re.fullmatch(r"-?\d+\.\d+", raw.replace(",","")) and raw.replace(",","").rstrip("0").rstrip(".")==r["gts"]:
                reasons["decimal"]+=1
            elif raw and raw.rstrip(".")==r["gts"]:
                reasons["trail_dot"]+=1
            else:
                reasons["other"]+=1
                if len(ex)<6:
                    ex.append((r["gts"], raw, r["output"][-100:].replace("\n"," ")))
        if exa and not logged:
            exact_not_logged+=1
    print(f"{label} n={n} logged {sum(r['score'] for r in rows)/n:.3f} exact_match {exact/n:.3f} soft {soft/n:.3f} soft_not_logged {soft_not_exact} reasons {reasons}")
    for e in ex:
        print("   ", e)
